'use strict';
const $=id=>document.getElementById(id);
const capabilities={ready:false,entries:[]};
const state={catalog:null,providers:[],account:null,format:null,template:null,revision:0,epoch:0,jobEpoch:0,job:null,jobs:[]};
// Display names are independent from the pinned profile IDs used by existing jobs.
function packAccount(account){const id=typeof account==='string'?account:account?.id;return state.catalog?.accounts?.find(a=>a.id===id)||account||{};}
function packCapability(account,name){return packAccount(account).capabilities?.[name];}
function packSerial(account){return packAccount(account).series_rules?.enabled===true;}
function topicName(account){return packAccount(account).display_name||packAccount(account).name||'İçerik üretimi';}
function displayText(value){let text=String(value||'');for(const account of state.catalog?.accounts||[]){for(const name of [account.handle,account.name].filter(Boolean).sort((a,b)=>b.length-a.length)){text=text.split(name).join(topicName(account));}}return text;}
function jobTitle(payload){return displayText(payload.input.title)||topicName(payload.account)+' / '+displayText(payload.format.name);}
function updateBrandHeading(){if(!state.account)return;$('account-name').textContent=$('brand-name').value.trim()||topicName(state.account);$('account-handle').textContent=[$('brand-handle').value.trim(),topicName(state.account),state.account.language.toUpperCase()].filter(Boolean).join(' · ');}
const statuses={versioned_pack_bounded_original_vectors:'Sürümlü vektör animatiği · sınırlı',source_confirmed:'Kaynak doğrulandı',user_named_pending_profile:'Profil teyidi bekliyor',source_confirmed_adapter_pending:'Kaynak var · adaptör bekliyor',format_confirmed_account_pending:'Format var · hesap eşleşmesi bekliyor',queued:'Kuyrukta',preparing:'Hazırlanıyor',prepared:'İnceleme kaynağı hazır',checked:'Teknik kontrol tamam',packaged:'İnceleme paketi hazır',failed:'Hazırlama hatası'};
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function humanError(text){const message=String(text||'Yerel işlem tamamlanmadı.');const messages={MALFORMED_CREDENTIAL:'API anahtarı boş veya güvenli header biçimine uymuyor. Seçili sağlayıcıya ait anahtarı yalnız bağlantı alanına girin; yerel demo için anahtar gerekmez.',LLM_DISABLED_START_DEMO_OR_EXPLICIT_LIVE_MODE:'Senaryo sağlayıcısı bağlantıları kapalı. Yerel demo anahtarsız çalışır; sağlayıcı için host açıkça demo/live modu seçmelidir.',ELEVENLABS_DISABLED_START_DEMO_OR_EXPLICIT_LIVE_MODE:'Ses sağlayıcısı kapalı. Yerel örnek sessizdir; gerçek ses ayrı bağlantı ve üretim onayı ister.'};if(messages[message])return messages[message];if(message.includes('local runtime missing'))return 'Yerel render motoru kurulu değil veya pinlerle eşleşmiyor. Proje kökünde python3 -m storymotion setup, sonra python3 -m storymotion doctor --engine all --strict çalıştırın.';return message;}
function notice(text,error=false){$('notice').textContent=error?humanError(text):text;$('notice').classList.toggle('error',error);}
async function api(path,data){const options={cache:'no-store',credentials:'same-origin'};if(data!==undefined){options.method='POST';options.headers={'Content-Type':'application/json','X-Storymotion-Local':'1'};options.body=JSON.stringify(data);}const r=await fetch(path,options);let value;try{value=await r.json();}catch{throw new Error('Sunucu yanıtı okunamadı. Yerel servisi kontrol et.');}if(!r.ok)throw new Error(value.error||'Yerel işlem tamamlanmadı.');return value;}
async function action(button,fn){const old=button.disabled;button.disabled=true;try{await fn();}catch(e){notice(e.message,true);}finally{button.disabled=old;}}
function tab(name){document.querySelectorAll('.tab-panel').forEach(n=>n.hidden=n.id!=='tab-'+name);document.querySelectorAll('[data-tab]').forEach(n=>{if(n.dataset.tab===name)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');});}
function options(select,items,selected){select.replaceChildren();items.forEach(i=>{const o=el('option',i.name);o.value=i.id;select.append(o);});if(selected&&items.some(i=>i.id===selected))select.value=selected;}
function accountList(){const list=$('account-list');list.replaceChildren();const cat=$('category').value;state.catalog.accounts.filter(a=>cat==='all'||a.category===cat).forEach(a=>{const b=el('button',topicName(a),'account');b.type='button';b.setAttribute('aria-pressed',String(state.account?.id===a.id));b.addEventListener('click',()=>selectAccount(a.id));list.append(b);});}
async function selectAccount(id){state.epoch++;const a=state.catalog.accounts.find(x=>x.id===id);state.account=a;if(typeof workflowAccountChanged==='function')workflowAccountChanged(id);if(typeof writingContextChanged==='function')writingContextChanged(id);state.job=null;state.jobEpoch++;voiceJobChanged(null);renderJobChanged(null);$('save-budget').disabled=true;$('check-job').disabled=true;$('export-job').disabled=true;$('selected-job').textContent='İş seçilmedi';$('qa-status').textContent='İş seçilmedi.';$('cover-preview').hidden=true;$('preview-empty').hidden=false;$('download').hidden=true;$('file-links').replaceChildren();accountList();updateBrandHeading();$('account-state').textContent=statuses[a.status]||a.status;$('tone').textContent=displayText(a.tone);$('visual-style').textContent=displayText(a.style);options($('format'),state.catalog.formats.filter(f=>a.formats.includes(f.id)));await selectFormat();}
async function selectFormat(){writerDraftChanged();const epoch=++state.epoch;const account=state.account;const fmt=state.catalog.formats.find(f=>f.id===$('format').value);state.format=fmt;const taskNames={text:'Metin',voice:'Ses',image:'Görsel',video:'Video',plan:'Plan',animation:'Yerel animasyon'};options($('provider-task'),fmt.allowed_tasks.map(id=>({id,name:taskNames[id]})),$('provider-task').value);providerList();state.template=null;$('starter-create').disabled=true;$('enqueue').disabled=true;$('save-template').disabled=true;$('format-state').textContent=fmt.state;$('format-description').textContent=displayText(fmt.description);
 try{const data=await api('/api/template/'+account.id+'/'+fmt.id);if(epoch!==state.epoch)return;state.template=data.template;state.revision=data.revision;$('template-json').value=JSON.stringify(data.template,null,2);$('revision').textContent='Revizyon '+data.revision;const v=data.template.video;const example=account.language==='en'?'This is a local workflow demo.':'Bu bir yerel iş akışı denemesidir.';$('title').value=displayText(v?.title)||(topicName(account)+' / '+fmt.name);$('brief').value=displayText(v?.brief)||example;$('content').value=v?.script||example;$('caption').value=displayText(v?.caption)||example;$('enqueue').disabled=false;$('starter-create').disabled=fmt.adapter!=='account-pack';$('save-template').disabled=false;tab('brief');}catch(e){if(epoch===state.epoch)notice(e.message,true);}}
function providerList(){const task=$('provider-task').value;const list=state.providers.filter(p=>p.capabilities.includes(task));options($('provider'),list);modelList();}
function modelList(){const p=state.providers.find(x=>x.id===$('provider').value);options($('model'),p?.models||[]);$('provider-state').textContent=!p?'Sağlayıcı yok.':p.key_kind==='none'?'Yerel adaptör · bağlantı gerektirmez.':p.id==='elevenlabs'?'Ses bağlantısı aşağıdaki adımda kurulur.':'Yerel plan seçimi · canlı bağlantı Senaryo yazarı sekmesindedir.';legacyWriterPanels();$('demo-key').value='';}
// Background status work may refresh data, but must not replace a changed view.
function jobSelectionSnapshot(){return {job:state.job?.id||null,jobEpoch:state.jobEpoch,accountEpoch:state.epoch,account:state.account?.id||null,payload:JSON.stringify(state.job?.payload),manual:typeof manualSceneSelectionRevision==='function'?manualSceneSelectionRevision():null,series:typeof seriesSelectionRevision==='function'?seriesSelectionRevision():null,rig:typeof rigSelectionRevision==='function'?rigSelectionRevision():null};}
function jobSelectionCurrent(s){return s.job===(state.job?.id||null)&&s.jobEpoch===state.jobEpoch&&s.accountEpoch===state.epoch&&s.account===(state.account?.id||null)&&s.payload===JSON.stringify(state.job?.payload)&&s.manual===(typeof manualSceneSelectionRevision==='function'?manualSceneSelectionRevision():null)&&s.series===(typeof seriesSelectionRevision==='function'?seriesSelectionRevision():null)&&s.rig===(typeof rigSelectionRevision==='function'?rigSelectionRevision():null);}
async function refreshJobs(){const data=await api('/api/jobs');state.jobs=data.jobs;const body=$('jobs');body.replaceChildren();$('queue-empty').hidden=!!data.jobs.length;data.jobs.forEach(j=>{const p=j.payload;const row=el('tr');const title=el('td');title.append(el('strong',jobTitle(p)),el('small',j.id));const binding=el('td',topicName(p.account));binding.append(el('small',displayText(p.format.name)));const status=el('td',statuses[j.status]||j.status);const actions=el('td');const prepare=el('button','Hazırla');prepare.addEventListener('click',()=>action(prepare,async()=>{const snapshot=jobSelectionSnapshot();await api('/api/jobs/'+j.id+'/prepare',{});await refreshJobs();if(!jobSelectionCurrent(snapshot))return;if(await selectJob(j.id,snapshot))notice('Yerel kaynak hazırlandı. Sağlayıcı çalıştırılmadı.');}));const select=el('button','İncele');select.addEventListener('click',()=>selectJob(j.id).catch(e=>notice(e.message,true)));actions.append(prepare,select);row.append(title,binding,status,actions);body.append(row);});}
async function selectJob(id,expectedView=null){if(expectedView&&!jobSelectionCurrent(expectedView))return false;const epoch=++state.jobEpoch,view=expectedView?{...expectedView,jobEpoch:epoch}:null;const data=await api('/api/jobs/'+id);if(epoch!==state.jobEpoch||(view&&!jobSelectionCurrent(view)))return false;state.job=data;voiceJobChanged(data);renderJobChanged(data);$('selected-job').textContent=jobTitle(data.payload);$('qa-status').textContent=JSON.stringify({status:statuses[data.status]||data.status,format:data.payload.format.state,provider_cost:'Bu görünüm ücret kaydı değildir; senaryo ve ses receipt dosyalarını ayrı inceleyin.',render:'Sürümlü konu animatikleri ve eski teknik fixture için motor seçimiyle yerel MP4 üretilebilir',human_review:'Bekliyor',error:data.error},null,2);const img=$('cover-preview');const has=data.files.includes('cover.svg');img.hidden=!has;$('preview-empty').hidden=has;if(has)img.src='/files/'+id+'/cover.svg';else img.removeAttribute('src');$('file-links').replaceChildren();data.files.filter(f=>f!=='package.zip').forEach(f=>{const a=el('a',f);a.href='/files/'+id+'/'+f;a.setAttribute('download','');$('file-links').append(a);});const ready=['prepared','checked','packaged'].includes(data.status);$('check-job').disabled=!ready;$('export-job').disabled=!ready;$('save-budget').disabled=false;$('download').hidden=true;tab('qa');return true;}
['brand-name','brand-handle'].forEach(id=>$(id).addEventListener('input',updateBrandHeading));
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>tab(b.dataset.tab)));
$('category').addEventListener('change',()=>{accountList();const c=$('category').value;const visible=state.catalog.accounts.filter(a=>c==='all'||a.category===c);if(visible.length&&!visible.some(a=>a.id===state.account?.id))selectAccount(visible[0].id);});$('format').addEventListener('change',selectFormat);$('provider-task').addEventListener('change',providerList);$('provider').addEventListener('change',modelList);
$('brief-form').addEventListener('submit',e=>{e.preventDefault();action($('enqueue'),async()=>{const epoch=state.epoch,jobEpoch=state.jobEpoch;const data={account:state.account.id,format:state.format.id,title:$('title').value,brief:$('brief').value,content:$('content').value,caption:$('caption').value,provider:$('provider').value,model:$('model').value,task:$('provider-task').value,template_revision:state.revision,brand_identity:{name:$('brand-name').value.trim(),handle:$('brand-handle').value.trim()}};const job=await api('/api/jobs',data);await refreshJobs();if(epoch===state.epoch&&jobEpoch===state.jobEpoch){tab('queue');notice('İş kuyruğa eklendi veya aynı içerik kimliğiyle tekrar kullanıldı.');}});});
$('starter-create').addEventListener('click',()=>action($('starter-create'),async()=>{const account=state.account,format=state.format,template=state.template,revision=state.revision,epoch=state.epoch,jobEpoch=state.jobEpoch;if(format?.adapter!=='account-pack'||!template?.video)throw Error('Önce sürümlü konu animatiğini seçin.');const video=template.video;const job=await api('/api/jobs',{account:account.id,format:format.id,title:video.title,brief:video.brief,content:video.script,caption:video.caption,provider:'local',model:'manual',task:'text',template_revision:revision,brand_identity:{name:$('brand-name').value.trim(),handle:$('brand-handle').value.trim()}});await refreshJobs();if(epoch!==state.epoch||jobEpoch!==state.jobEpoch)return;tab('queue');notice('Sabit yerel örnek kuyruğa alındı. Hazırla ile devam edin; API anahtarı veya sağlayıcı çağrısı yok.');}));
$('save-template').addEventListener('click',()=>action($('save-template'),async()=>{let value;try{value=JSON.parse($('template-json').value);}catch{throw new Error('Şablon geçerli JSON olmalı.');}const epoch=state.epoch;const r=await api('/api/template',{account:state.account.id,format:state.format.id,revision:state.revision,template:value});if(epoch!==state.epoch)return;state.template=r.template;state.revision=r.revision;$('revision').textContent='Revizyon '+r.revision;if(value.video){$('content').value=value.video.script;$('title').value=displayText(value.video.title);$('brief').value=displayText(value.video.brief);$('caption').value=displayText(value.video.caption);writerDraftChanged();}notice('Şablon kaydedildi. Önceki işler kendi şablon revizyonunu korur.');}));
$('run-worker').addEventListener('click',()=>action($('run-worker'),async()=>{const r=await api('/api/worker/run-once',{});notice(r.status==='already_running'?'Yerel işçi zaten çalışıyor.':'Bir kuyruk işi yerel hazırlama için alındı; sağlayıcı/render çağrısı yok. Sonucu görmek için kuyruğu yenile.');}));
$('reload-template').addEventListener('click',selectFormat);$('refresh-jobs').addEventListener('click',()=>action($('refresh-jobs'),refreshJobs));
$('key-form').addEventListener('submit',e=>{e.preventDefault();action($('save-key'),async()=>{const input=$('demo-key');const value=input.value;input.value='';if(!/^FAKE_[A-Za-z0-9_]{3,80}$/.test(value))throw new Error('Yalnız FAKE_ ile başlayan örnek değer kullan. Gerçek anahtar gönderilmedi.');try{await api('/api/keys',{provider:$('provider').value,value});$('key-state').textContent='Sahte değer RAM alanında; 15 dakikada veya sunucu kapanınca silinir. Bağlantı doğrulanmadı.';}finally{input.value='';}});});
