$('budget-form').addEventListener('submit',e=>{e.preventDefault();action($('save-budget'),async()=>{if(!state.job)throw new Error('Önce kuyruktan bir iş seç.');await api('/api/jobs/'+state.job.id+'/budget',{max_usd:$('budget').value,quote_source:$('quote-source').value,approved_by:$('approved-by').value});notice('Yerel plan limiti kaydedildi. Canlı harcama açılmadı.');});});
$('check-job').addEventListener('click',()=>action($('check-job'),async()=>{const snapshot=jobSelectionSnapshot(),id=state.job?.id;if(!id)return;await api('/api/jobs/'+id+'/check',{});await refreshJobs();if(!jobSelectionCurrent(snapshot))return;if(await selectJob(id,snapshot))notice('Teknik kontrol tamamlandı. Yaratıcı onay ve dinleme ayrı bekliyor.');}));
$('export-job').addEventListener('click',()=>action($('export-job'),async()=>{const id=state.job.id;const r=await api('/api/jobs/'+id+'/export',{});if(state.job?.id!==id)return;$('download').href=r.url;$('download').hidden=false;notice('İnceleme ZIP’i oluşturuldu; yayın yapılmadı.');await refreshJobs();}));
window.addEventListener('pagehide',()=>{$('demo-key').value='';});
async function bootstrapSession(){
 const hash=window.location?.hash||'';
 if(!hash.startsWith('#bootstrap='))return;
 const token=hash.slice('#bootstrap='.length);
 window.history.replaceState(null,'',window.location.pathname+window.location.search);
 if(!/^[A-Za-z0-9_-]{43}$/.test(token))throw Error('Yerel oturum bağlantısı geçersiz; paneli yeniden başlatın.');
 const response=await fetch('/api/bootstrap',{method:'POST',cache:'no-store',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Storymotion-Local':'1','X-Storymotion-Token':token},body:'{}'});
 if(!response.ok)throw Error('Yerel oturum açılamadı; tek kullanımlık bağlantı için paneli yeniden başlatın.');
}
async function start(){try{await bootstrapSession();const d=await api('/api/catalog');state.catalog=d.catalog;state.providers=d.providers.providers;capabilityCatalog(d.capabilities);voiceConfig(d.elevenlabs);writerConfig(d.llm);d.catalog.categories.forEach(c=>{const o=el('option',c.name);o.value=c.id;$('category').append(o);});$('inventory-note').textContent=displayText(d.catalog.inventory_note);$('candidates').replaceChildren(...d.catalog.unassigned_candidates.map(c=>el('p',c.name+' — '+c.state)));providerList();await selectAccount(d.catalog.accounts[0].id);await refreshJobs();}catch(e){notice(e.message,true);}}
function approvalInputs(prefix){return {max_usd:$(prefix+'-max-usd').value,estimate_usd:$(prefix+'-estimate-usd').value,quote_source:$(prefix+'-quote-source').value,ack_unknown_cost:$(prefix+'-cost-ack').checked,rights_confirmed:$(prefix+'-rights-ack').checked};}
function approvalBudget(mode,inputs){return mode==='demo'?null:{max_usd:inputs.max_usd,estimate_usd:inputs.estimate_usd,quote_source:inputs.quote_source,verified_by_user:true};}
const voice={mode:'off',connection:null,metadata:null,preview:null,request:null,epoch:0,timer:null,pending:null};
const audioBind={epoch:0,source:null,job:null,jobEpoch:0,voiceEpoch:0,identity:null,pending:null};
function showVoicePart(id,shown){const node=$(id),moveFocus=!shown&&node.contains(document.activeElement);node.hidden=!shown;if(moveFocus){const target=voice.mode==='off'?$('el-how').querySelector('summary'):voice.connection?$('el-refresh'):$('el-key');target?.focus();}}
function voiceViewState(mode,connection,preview,selected){const enabled=mode!=='off',connected=enabled&&!!connection;return {enabled,connected,select:connected,text:connected,approve:connected&&!!preview,canPreview:connected&&!!selected&&!selected?.payload?.edit_revision&&!selected?.payload?.scene_plan_revision&&!selected?.payload?.rig_revision};}
function voiceConfig(config){voice.mode=config?.mode||'off';connectionSummary();$('el-mode').textContent=voice.mode==='off'?'Kapalı · bu oturumda bağlantı veya ses üretimi yok.':voice.mode==='demo'?'Demo · sentetik ses, ücret yok.':'Canlı mod · her üretim ayrı onay gerektirir.';$('el-key').placeholder=voice.mode==='demo'?'FAKE_ELEVENLABS_DEMO_ONLY':'API anahtarınız';voiceControls();}
function voiceResetPreview(){voice.preview=null;voice.request=null;voice.epoch++;audioBindReset();if(voice.timer)clearTimeout(voice.timer);$('el-preview-data').textContent='Önizleme bekliyor.';$('el-exact-text').textContent='';$('el-cost-ack').checked=false;$('el-rights-ack').checked=false;$('el-generate').disabled=true;$('el-cancel').disabled=true;$('el-cancel').hidden=true;$('el-downloads').replaceChildren();voiceControls();}
function voiceJobChanged(job){voiceResetPreview();$('el-tts').value=job?.payload?.input?.content||'';voiceControls();if(job)voiceLoad(job.id).catch(e=>{$('el-status').textContent=e.message;});}
function voiceBudgetValid(){if(voice.mode!=='live')return true;const max=$('el-max-usd'),estimate=$('el-estimate-usd'),source=$('el-quote-source');return max.value!==''&&estimate.value!==''&&Number.isFinite(Number(max.value))&&Number.isFinite(Number(estimate.value))&&Number(max.value)>=0&&Number(max.value)<=10000&&Number(estimate.value)>=0&&Number(estimate.value)<=Number(max.value)&&!!source.value.trim();}
function voiceApprovalContext(preview){return JSON.stringify({mode:voice.mode,connection:voice.connection,job:state.job?.id,request:voice.request,preview_request:preview.request,maximum_characters:preview.characters,tts_text:$('el-tts').value,voice_id:$('el-voice').value,model_id:$('el-model').value,inputs:approvalInputs('el')});}
function voiceApprovalCurrent(snapshot,requirePreview=true){return snapshot.epoch===voice.epoch&&snapshot.metadata===voice.metadata&&voice.mode!=='off'&&(!requirePreview||voice.preview===snapshot.preview)&&voiceApprovalContext(snapshot.preview)===snapshot.context&&voiceBudgetValid()&&$('el-cost-ack').checked&&$('el-rights-ack').checked;}
function voiceApprovalChanged(clearConsent=false){if(voice.pending){voiceResetPreview();$('el-status').textContent='Onay bilgileri değişti. Gönderimden önce yeni önizleme ve iki açık onay gerekiyor.';}else if(clearConsent){$('el-cost-ack').checked=false;$('el-rights-ack').checked=false;}voiceControls();}
function voiceControls(){const view=voiceViewState(voice.mode,voice.connection,voice.preview,state.job),wasInConnect=$('el-connect-form').contains(document.activeElement),wasInFlow=$('el-flow').contains(document.activeElement);$('el-flow').hidden=!view.enabled;$('el-how').hidden=view.enabled;$('el-connect-form').hidden=view.connected;showVoicePart('el-connected',view.connected);showVoicePart('el-step-select',view.select);showVoicePart('el-step-text',view.text);showVoicePart('el-step-approve',view.approve);$('el-connect').disabled=!view.enabled;$('el-disconnect').disabled=!view.connected;$('el-refresh').disabled=!view.connected;$('el-voice').disabled=!view.connected;$('el-model').disabled=!view.connected;$('el-tts').disabled=!view.canPreview;$('el-preview').disabled=!view.canPreview||!!voice.pending;$('el-job-hint').textContent=state.job?'Seçili iş: '+jobTitle(state.job.payload):'Önce kuyruktan bir iş seçin.';$('el-connection-summary').textContent=view.connected?'Oturumluk bağlantı açık · henüz üretim izni verilmedi.':'';$('el-live-budget').hidden=voice.mode!=='live';['el-max-usd','el-estimate-usd','el-quote-source'].forEach(id=>$(id).required=voice.mode==='live');$('el-generate').disabled=!!voice.pending||!view.approve||!$('el-cost-ack').checked||!$('el-rights-ack').checked||!voiceBudgetValid();audioBindControls();if(wasInConnect&&view.connected)$('el-voice').focus();else if(wasInFlow&&!view.enabled)$('el-how').querySelector('summary').focus();}
function audioBindInputs(){return {approved_by:$('audio-bind-approved-by').value,rights_note:$('audio-bind-rights-note').value,rights_confirmed:$('audio-bind-rights').checked};}
function audioBindReady(){return !!audioBind.source&&audioBind.source.status==='completed'&&!!audioBind.source.artifact&&/^[a-f0-9]{32}$/.test(audioBind.source.request)&&/^[a-f0-9]{24}$/.test(audioBind.job||'')&&state.job?.id===audioBind.job&&state.jobEpoch===audioBind.jobEpoch&&voice.request===audioBind.source.request&&voice.epoch===audioBind.voiceEpoch;}
function audioBindInputsValid(){const input=audioBindInputs();return !!input.approved_by.trim()&&input.approved_by.length<=200&&!!input.rights_note.trim()&&input.rights_note.length<=1000&&input.rights_confirmed;}
function audioBindControls(){const details=$('audio-bind-step'),shown=audioBindReady(),focused=details.contains(document.activeElement);details.hidden=!shown;$('audio-bind-submit').disabled=!shown||!!audioBind.pending||!audioBindInputsValid();details.setAttribute('aria-busy',String(!!audioBind.pending));if(!shown&&focused)$('el-title').focus();}
function audioBindReset(){audioBind.epoch++;audioBind.source=null;audioBind.job=null;audioBind.identity=null;$('audio-bind-step').open=false;$('audio-bind-approved-by').value='';$('audio-bind-rights-note').value='';$('audio-bind-rights').checked=false;$('audio-bind-status').textContent='';$('audio-bind-source').textContent='';audioBindControls();}
function audioBindSource(job,item){if(item?.status!=='completed'||!item.artifact||!/^[a-f0-9]{32}$/.test(item.request||'')){audioBindReset();return;}const identity=JSON.stringify({job,request:item.request,artifact:item.artifact});if(identity!==audioBind.identity)audioBindReset();audioBind.identity=identity;audioBind.source=item;audioBind.job=job;audioBind.jobEpoch=state.jobEpoch;audioBind.voiceEpoch=voice.epoch;$('audio-bind-source').textContent='Tamamlanmış ses → '+jobTitle(state.job.payload)+'.';audioBindControls();}
