async function voiceLoad(job,request){const epoch=voice.epoch;let data;try{data=await api('/api/elevenlabs/state',{job});}catch(error){if(epoch===voice.epoch&&state.job?.id===job)audioBindReset();throw error;}if(epoch!==voice.epoch||state.job?.id!==job)return;const item=request?data.requests.find(r=>r.request===request):data.requests[0];if(!item){audioBindReset();return;}voice.request=item.request;audioBindSource(job,item);$('el-status').textContent=JSON.stringify(item,null,2);$('el-cancel').disabled=!['preview','approved','dispatching'].includes(item.status);$('el-cancel').hidden=$('el-cancel').disabled;$('el-downloads').replaceChildren();if(item.artifact){Object.keys(item.artifact.files).forEach(name=>{const link=el('a',name);link.href='/voice-files/elevenlabs/'+item.request+'/'+name;link.setAttribute('download','');$('el-downloads').append(link);});$('check-job').disabled=true;$('export-job').disabled=true;}
 if(item.status==='dispatching')voice.timer=setTimeout(()=>voiceLoad(job,item.request).catch(e=>{$('el-status').textContent=e.message;}),1000);
 if(['completed','uncertain','received_after_cancel_review','failed_known_no_retry','blocked_before_dispatch','invalidated','cancelled'].includes(item.status)){voice.preview=null;$('el-generate').disabled=true;}voiceControls();}
