 const snapshot={preview,epoch:voice.epoch,metadata:voice.metadata,connection:voice.connection,job:state.job.id,request:preview.request,characters:preview.characters,context:voiceApprovalContext(preview),budget:approvalBudget(voice.mode,approvalInputs('el'))};voice.pending=snapshot;voiceControls();
