const editFamilyNames={'manual-account-scene-plan':'Elle seçilmiş sahne türleri','customer-raster-annotation':'Yerel görsel açıklaması','hinged-latch':'Mandal ve kapak çizimi','envelope-corner-continuity':'Zarf ve köşe izi','phone-context-observation':'Telefon ve bekleme anı','approval-conveyor':'İstek ve onay şeması'};
