function editPlanJobChanged(job){const details=$('edit-plan-details'),focused=details.contains(document.activeElement);details.hidden=true;$('edit-plan-data').textContent='';$('edit-plan-summary').textContent='';const supported=job?.payload?.format?.adapter==='account-pack';$('edit-plan-read').disabled=!supported;if(focused)(supported?$('edit-plan-read'):$('render-title')).focus();}
