function renderJobChanged(job){renderPlayerClear();if(typeof rigJobChanged==='function')rigJobChanged(job);if(typeof seriesJobChanged==='function')seriesJobChanged(job);if(typeof manualSceneJobChanged==='function')manualSceneJobChanged(job);if(typeof localAudioJobChanged==='function')localAudioJobChanged(job);if(typeof rasterJobChanged==='function')rasterJobChanged(job);sceneEditChanged(job);editPlanJobChanged(job);if(typeof reviewJobChanged==='function')reviewJobChanged(job);localRender.epoch++;if(localRender.timer)clearTimeout(localRender.timer);$('render-downloads').replaceChildren();$('render-status').textContent='Render başlatılmadı.';$('render-cancel').disabled=true;const adapter=job?.payload?.format?.adapter;const supported=['hyperframes-fixture','account-pack'].includes(adapter);$('render-start').disabled=!supported;$('render-engine').disabled=!supported;$('render-scope').textContent=supported?(adapter==='account-pack'?(job?.payload?.template?.template?.video?.scene_plan?'Elle seçilmiş, kaynağa bağlı sahneler. İnsan anlam/kaynak kabulü bekler. ':job?.payload?.template?.template?.video?.raster?'Seçili yerel görsel; kırpma, işaretleme ve kamera. Görsel/anlatım insan incelemesi bekler. ':'Sürümlü konu prosedürüyle sınırlı özgün vektör animatiği. İnsan incelemesi bekler. '):'Sessiz teknik fixture animatiği. ')+'Motor işe pinlenir; ücretli çağrı yapılmaz. Yeni ses sonrası eski timing ile render engellenir.':'Bu konunun tam video adaptörü henüz yok; plan veya metin çıktısı MP4 değildir.';if(supported)renderLoad(job.id,$('render-engine').value).catch(e=>notice(e.message,true));}
async function renderLoad(job,engine){const epoch=localRender.epoch;let data;try{data=await api('/api/jobs/'+job+'/render-state',{engine});}catch(error){if(epoch===localRender.epoch&&state.job?.id===job&&$('render-engine').value===engine){renderPlayerClear();if(typeof seriesRenderState==='function')seriesRenderState(job,engine,null);}throw error;}if(epoch!==localRender.epoch||state.job?.id!==job||$('render-engine').value!==engine)return;if(typeof seriesRenderState==='function')seriesRenderState(job,engine,data);if(typeof reviewRenderState==='function')reviewRenderState(job,engine,data);$('render-status').textContent=JSON.stringify(data,null,2);$('render-downloads').replaceChildren();const running=data.status==='running';$('render-start').disabled=running;$('render-cancel').disabled=!running;const validFiles=data.files&&typeof data.files==='object'&&!Array.isArray(data.files)?data.files:{};if(data.status==='complete'){const name=/^[a-f0-9]{64}$/.test(validFiles['render-mobile.mp4']||'')?'render-mobile.mp4':/^[a-f0-9]{64}$/.test(validFiles['render-1080.mp4']||'')?'render-1080.mp4':null;if(name){const player=$('render-preview'),url='/render-files/'+job+'/'+engine+'/'+name;if(player.getAttribute?.('src')!==url)player.src=url;player.hidden=false;$('render-preview-hint').hidden=false;}else renderPlayerClear();}else renderPlayerClear();if(data.status==='complete')Object.keys(validFiles).forEach(name=>{const a=el('a',name);a.href='/render-files/'+job+'/'+engine+'/'+name;a.setAttribute('download','');$('render-downloads').append(a);});if(running)localRender.timer=setTimeout(()=>renderLoad(job,engine).catch(e=>notice(e.message,true)),1000);}
