function legacyWriterPanels(){const p=state.providers.find(x=>x.id===$('provider').value),demo=writer.mode==='demo',relevant=['text','plan'].includes($('provider-task').value);$('llm-demo').hidden=!demo||!p||p.key_kind==='none'||!relevant;$('llm-plan').hidden=!demo||!relevant;$('save-key').disabled=!demo||!p||p.key_kind==='none';}
function writerAllowedProviders(){return writer.providers.filter(provider=>capabilities.ready&&capabilities.entries.some(row=>row.provider===provider&&row.capability==='text'&&row.ui_target==='writer'&&capabilityRegistered(row)));}
