$('writer-connect-form').addEventListener('submit',event=>{event.preventDefault();writerAction('connect',async()=>{const input=$('writer-key');let value=input.value;input.value='';const provider=$('writer-provider').value;let created=null;try{if(writer.mode==='off')throw new Error('Senaryo yazarı kapalı.');if(writer.mode==='demo'&&!/^(FAKE_|TEST_ONLY_)/.test(value))throw new Error('Demo modunda yalnız sentetik FAKE_ / TEST_ONLY_ değer kullanın.');if(!writerAllowedProviders().includes(provider))throw new Error('Bu sağlayıcı için kayıtlı ve host tarafından etkinleştirilmiş metin adaptörü gerekiyor.');await writerDropConnection('Model listesi okunuyor; üretim başlamadı.');const epoch=writer.epoch;const result=await api('/api/llm/connect',{provider,value});created=result.connection;if(epoch!==writer.epoch){if(result.connection)await api('/api/llm/disconnect',{connection:result.connection});return;}const ttl=Number(result.expires_in_seconds||result.config?.ttl_seconds||result.ttl_seconds);if(!/^[a-f0-9]{32}$/.test(result.connection||'')||!Number.isFinite(ttl)||ttl<=0)throw new Error('Oturum süresi doğrulanamadı.');writer.connection=result.connection;writer.provider=provider;writer.expiresAt=Date.now()+Math.min(ttl,3600)*1000;writerMetadata(result.metadata);const connection=writer.connection;writer.connectionTimer=setTimeout(()=>{if(writer.connection===connection)writerDropConnection('Oturum süresi doldu; anahtar silindi. Yeniden bağlanın.').catch(()=>{});},Math.min(ttl,3600)*1000);$('writer-status').textContent='Model listesi alındı. Henüz üretim izni verilmedi.';}catch(error){if(created){if(writer.connection===created){try{await writerDropConnection('Bağlantı kurulamadı; anahtar silindi.');}catch{}}else{try{await api('/api/llm/disconnect',{connection:created});}catch{}}}throw error;}finally{value='';input.value='';}});});
