// Catalog entries describe capabilities; only host registration + mode config unlocks navigation.
const capabilityLabels={text:'Metin',voice:'Metinden sese',image_generation:'Görsel üretimi',video_generation:'Video üretimi',sound_effects:'Ses efekti',music:'Müzik',animation_render:'Yerel animasyon renderi'};
const capabilityImplemented=new Set(['implemented_contract_tested_live_unverified','implemented_local_runtime_unverified']);
function capabilityRegistered(row){return row?.adapter_registered===true&&row.selectable===true&&capabilityImplemented.has(row.status);}
function capabilityFamily(row){if(row.capability==='animation_render'&&row.execution==='local')return 'render';if(row.capability==='text')return 'text';if(['voice','sound_effects','music'].includes(row.capability))return 'audio';if(row.capability==='image_generation')return 'image';if(row.capability==='video_generation')return 'video';return ['text','image','video','audio'].includes(row.category)?row.category:'unknown';}
function capabilityCatalog(value){capabilities.ready=Array.isArray(value);capabilities.entries=(Array.isArray(value)?value:[]).slice(0,2000).filter(row=>row&&typeof row==='object'&&typeof row.provider==='string'&&/^[a-z][a-z0-9_-]{0,79}$/.test(row.provider)&&typeof row.capability==='string'&&/^[a-z][a-z0-9_-]{0,79}$/.test(row.capability)&&typeof row.name==='string').map(row=>({...row,name:row.name.slice(0,160)}));writerRefreshProviders();writerControls();capabilityList();}
function capabilityAction(row){if(!capabilityRegistered(row))return null;if(row.capability==='text'&&row.ui_target==='writer'&&writerAllowedProviders().includes(row.provider))return 'writer';if(row.capability==='voice'&&row.ui_target==='voice'&&row.provider==='elevenlabs')return 'voice';if(row.capability==='animation_render'&&row.ui_target==='render'&&row.execution==='local'&&['hyperframes','remotion'].includes(row.provider))return 'render';return null;}
function capabilityStatus(row){if(row.status==='planned')return 'Planlandı · bağlantı yok';if(row.status==='no_verified_public_api')return 'Doğrulanmış API yok · bağlantı yok';if(row.status==='unknown_not_verified')return 'API durumu belirsiz · bağlantı yok';if(!capabilityRegistered(row))return 'Kayıtlı adaptör yok · bağlantı yok';return row.execution==='local'?'Yerel adaptör kayıtlı':'Adaptör kayıtlı · canlı test doğrulanmadı';}
function capabilityDocURL(value){return typeof value==='string'&&value.length<=1000&&/^https:\/\/[A-Za-z0-9.-]+(?::443)?(?:[/?#][^\s]*)?$/.test(value)&&!value.includes('@')?value:null;}
function capabilityOpen(row){const action=capabilityAction(row);if(!action)return;if(action==='writer'){tab('writer');if(writer.connection&&writer.provider!==row.provider){$('writer-status').textContent='Mevcut '+writerProviderNames[writer.provider]+' bağlantısı açık. Sağlayıcı değiştirmek için önce bu bağlantıyı kesin; anahtar başka sağlayıcıya taşınmaz.';$('writer-disconnect').focus();return;}if(!writer.connection){$('writer-key').value='';$('writer-provider').value=row.provider;writerInvalidate();writer.metadata=null;options($('writer-model'),[]);writerControls();}$('writer-status').textContent='Katalog yalnız yazarı açtı; bağlantı veya üretim başlatılmadı.';if(writer.mode==='off')$('writer-how').querySelector('summary').focus();else if(writer.connection)$('writer-model').focus();else $('writer-key').focus();return;}if(action==='voice'){if(voice.mode==='off')$('el-how').querySelector('summary').focus();else if(voice.connection)$('el-voice').focus();else $('el-key').focus();return;}tab('qa');$('render-title').focus();notice('Render alanı açıldı. Motoru ve işi bu alanda açıkça seçin; render başlatılmadı.');}
function capabilityList(){const list=$('capability-list');list.replaceChildren();const category=$('capability-category').value,filter=$('capability-status-filter').value;const entries=capabilities.entries.filter(row=>(category==='all'||capabilityFamily(row)===category)&&(filter==='all'||(filter==='registered')===capabilityRegistered(row)));$('capability-summary').textContent=capabilities.ready?entries.length+' kayıt gösteriliyor · '+capabilities.entries.filter(capabilityRegistered).length+' kayıtlı adaptör. Katalog bağlantı ve üretim başlatmaz.':'Katalog sunucudan henüz gelmedi; yeni bağlantı seçimi kapalıdır.';$('capability-empty').hidden=!capabilities.ready||!!entries.length;entries.forEach((row,index)=>{const article=el('article',undefined,'capability-row');article.dataset.provider=row.provider;article.dataset.capability=row.capability;const content=el('div');content.append(el('h3',row.name+' · '+(capabilityLabels[row.capability]||row.capability)));const stateClass=capabilityRegistered(row)?'registered':row.status==='planned'?'planned':'unknown';content.append(el('p',capabilityStatus(row),'capability-status '+stateClass));const action=capabilityAction(row),reason=el('p',String(row.disabled_reason==='adapter_not_registered'?'Bu yetenek için üretim adaptörü henüz eklenmedi.':row.disabled_reason||(capabilityRegistered(row)?action==='render'?'Yerel motor alanını açar. Anahtar gerekmez; bu kayıt kurulum veya doctor sonucu değildir.':action?'Bağlantı alanını açar; oturumluk anahtar ve üretim onayı ilgili akışta ayrı alınır.':'Bu host ayarında bağlantı akışı etkin değil.':'Bu yetenek için çalışan adaptör kaydı bulunmuyor.')).slice(0,600),'hint');reason.setAttribute('id','capability-reason-'+index);content.append(reason);const button=el('button',action==='writer'?'Yazarı aç':action==='voice'?'Ses alanını göster':action==='render'?'Render alanını aç':'Bağlantı yok','capability-action');button.type='button';button.disabled=!action;button.setAttribute('aria-disabled',String(!action));button.setAttribute('aria-describedby',reason.id);if(action)button.addEventListener('click',()=>capabilityOpen(row));const details=el('details',undefined,'capability-details');details.append(el('summary','Resmi belge ve sınırlar'));const docs=Array.isArray(row.documentation)?row.documentation.slice(0,10):[];for(const doc of docs){const url=capabilityDocURL(doc.url);if(!url)continue;const link=el('a',String(doc.title||'Resmi doküman').slice(0,160));link.href=url;link.target='_blank';link.rel='noopener noreferrer';details.append(link);}details.append(el('p',row.execution==='local'?'Yerel kod kaydıdır; bu cihazdaki kurulum, doctor ve render kabulü ayrıca gerekir. Sağlayıcı anahtarı kullanılmaz.':'Canlı doğrulama: '+(row.live_verified===true?'Sunucu kaydı var; kendi hesabınızın erişimi ayrıca doğrulanır.':'Yapılmadı')+'. Kredi, limit ve saklama koşulları hesabınız için ayrıca doğrulanmalıdır.'));article.append(content,button,details);list.append(article);});}
$('capability-category').addEventListener('change',capabilityList);
$('capability-status-filter').addEventListener('change',capabilityList);

start();
